import random
import time

def game():
    print("✊✌✋ ジャンケンゲーム ✊✌✋")
    while True:
        user = input("✊グー、1:✌チョキ、2:✋パーから選択してください: ")
        if user == "0":
            user_hand = 0
        elif user == "1":
            user_hand = 1
        elif user == "2":
            user_hand = 2
        else:
            print("正しい入力をしてください")
            continue

        computer_hand = random.randint(0, 2)
        print(f"\nあなたの手: {['グー', 'チョキ', 'パー'][user_hand]}")
        print(f"コンピューターの手: {['グー', 'チョキ', 'パー'][computer_hand]}\n")

        result = (user_hand - computer_hand + 3) % 3
        if result == 0:
            print("あいこです。")
        elif result == 1:
            print("負け😭 -1点")
            score -= 1
        else:
            print("勝ち😀 +3点")
            score += 3

        print(f"スコア: {score}\n")

        play_again = input("ゲームを続けるかどうかを選択してください (y/n): ")
        if play_again.lower() != "y":
            break

score = 0
game()
